// In-memory compact base JPEG image buffers (real photography scenes)
// - Golden Gate Bridge sunset landscape for Apple iPhone 16 Pro Max preset
// - Professional Studio ColorChecker calibration scene for Canon EOS R5 DSLR preset

export const GOLDEN_GATE_JPEG_BASE64 =
  "";

export const STUDIO_TARGET_JPEG_BASE64 =
  "";

export function decodeBase64Jpeg(base64: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    const buf = Buffer.from(base64, "base64");
    return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
  }
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
